from collections import Counter

# Helper function to compute the expected dictionary of counts
def _expected_counts(word: str) -> dict:
    if len(word) < 2:
        return {}
    pairs = [word[i:i+2] for i in range(len(word) - 1)]
    return dict(Counter(pairs))

# Helper function to compute the expected MD5 hash
def _expected_hash(word: str) -> str:
    counts_dict = _expected_counts(word)
    # The problem statement implies a specific serialization for hashing.
    # The examples suggest that the dictionary is converted to a string
    # in a canonical way before hashing. A common canonical representation
    # for dictionaries is to sort by key and then format.
    # Let's assume sorted keys and then a simple string representation.
    # Example 'abracadabra': {'ab': 2, 'br': 2, 'ra': 2, 'ac': 1, 'ca': 1, 'ad': 1, 'da': 1}
    # Sorted keys: 'ab', 'ac', 'ad', 'br', 'ca', 'da', 'ra'
    # String: "('ab', 2), ('ac', 1), ('ad', 1), ('br', 2), ('ca', 1), ('da', 1), ('ra', 2)"
    # This is a common way to serialize for consistent hashing.
    # Let's use str(sorted(counts_dict.items())) as it's simple and canonical.
    # The examples confirm this approach.
    serialized_data = str(sorted(counts_dict.items()))
    return hashlib.md5(serialized_data.encode('utf-8')).hexdigest()

