@given(word=st.text(min_size=2, max_size=12, alphabet=st.characters(min_codepoint=1, max_codepoint=127)))
@settings(max_examples=50, deadline=None)
def test_reversal_produces_different_hash_unless_palindrome(word: str):
    # Reversing a word generally changes the pairs, thus the hash.
    # If the word is a palindrome, the pairs are also reversed, but the counts
    # of the *original* pairs might be the same if the pairs themselves are palindromic.
    # However, the problem asks for counts of adjacent pairs from left to right.
    # So, 'ab' in 'aba' is different from 'ba' in 'aba' (reversed).
    # The set of pairs will be different unless the word is very specific.
    reversed_word = word[::-1]
    if word == reversed_word: # Palindrome
        # For palindromes, the set of pairs might be the same, but their order in the
        # canonical representation might differ if the pairs themselves are not palindromic.
        # E.g., 'aba': pairs {'ab':1, 'ba':1}. Reversed 'aba': pairs {'ab':1, 'ba':1}. Same.
        # E.g., 'racecar': pairs {'ra':1, 'ac':1, 'ce':1, 'ec':1, 'ca':1, 'ar':1}.
        # Reversed 'racecar': pairs {'ra':1, 'ac':1, 'ce':1, 'ec':1, 'ca':1, 'ar':1}. Same.
        # So for palindromes, the hash should be the same.
        assert task_func(word) == task_func(reversed_word), \
            f"Expected hash for palindrome '{word}' and its reverse to be same, but got {task_func(word)} vs {task_func(reversed_word)}"
    else:
        # For non-palindromes, the hash should generally be different.
        # There might be extremely rare cases where they are the same by coincidence,
        # but it's a strong property to check.
        assert task_func(word) != task_func(reversed_word), \
            f"Expected hash for '{word}' and its reverse '{reversed_word}' to be different, but got same hash {task_func(word)}"

@given(word=st.text(min_size=2, max_size=12, alphabet=st.characters(min_codepoint=1, max_codepoint=127)))
@settings(max_examples=50, deadline=None)
def test_case_sensitivity_impact(word: str):
    # The problem statement does not specify case sensitivity.
    # Standard string operations are case-sensitive.
    # Assuming 'aB' is different from 'ab'.
    # If the implementation converts to lower/upper, this test will fail.
    # We expect different hashes for different casing.
    upper_word = word.upper()
    lower_word = word.lower()
    if word != upper_word: # Only test if there's a change in casing
        assert task_func(word) != task_func(upper_word), \
            f"Expected different hashes for '{word}' and '{upper_word}' due to case sensitivity, but got same hash {task_func(word)}"
    if word != lower_word:
        assert task_func(word) != task_func(lower_word), \
            f"Expected different hashes for '{word}' and '{lower_word}' due to case sensitivity, but got same hash {task_func(word)}"

